nesting.source:
type Item = { name:string }
type Panel = { title:string content items:Item+ }

let root(wide:bool) =
  <Panel title="outer">
    <Panel title="inner">
      <Item name="a" />
    </Panel>
    if wide {
      <Item name="b" />
    }
  </Panel>

