childCounts.source:
type Item = { name:string }
type Panel = { content items:Item+ }

let kids(): Item+ = { <Item name="k" /> }

let root(wide:bool, names:string+, n:int) =
  <Panel>
    <Item name="x" />
    // A note is not a child.
    if wide {
      <Item name="b" />
      <Item name="c" />
    } else {
      <Item name="d" />
    }
    for title in names {
      <Item name={title} />
    }
    if n is {
      0 => <Item name="zero" />
      else => <Item name="many" />
    }
  </Panel>

let given =
  <Panel>
    <Item name="y" />
    {kids()}
  </Panel>
